def rebalance(questions):
    for i, q in enumerate(questions):
        target = i % 4
        a = q["ans"]
        if a != target:
            q["opts"][a], q["opts"][target] = q["opts"][target], q["opts"][a]
            q["ans"] = target
    return questions


def _validate(name, lessons, questions, want_ch):
    problems = []
    if len(lessons) != want_ch:
        problems.append(f"  {name}: {len(lessons)} lessons (want {want_ch})")
    short = [f"{l['title'][:40]} ({len(l['html'])})" for l in lessons if len(l["html"]) < 2500]
    if short:
        problems.append(f"  {name} below depth: {short}")
    if len(questions) != 35:
        problems.append(f"  {name}: {len(questions)} questions (want 35)")
    for q in questions:
        if len(q["opts"]) != 4 or not (0 <= q["ans"] <= 3):
            problems.append(f"  {name} malformed '{q['q'][:40]}'")
    if "ERPNext" in json.dumps({"l": lessons, "q": questions}):
        problems.append(f"  {name}: ERPNext branding leakage")
    return problems


def main():
    root = os.getcwd()
    with io.open(os.path.join(root, INIT), encoding="utf-8") as f:
        init = f.read()
    with io.open(os.path.join(root, DATA_PATH), encoding="utf-8") as f:
        data = json.load(f)

    if '"3.157.0"' in init:
        print("Already applied. Nothing to do.")
        return
    if '"3.156.0"' not in init:
        sys.exit("ABORT: not at v3.156.0.")
    for k in ("voucher_programme", "honest_counter"):
        if k not in data:
            sys.exit(f"ABORT: {k} module not found in data file.")

    problems = _validate("POS7", LESSONS_M7, QUESTIONS_M7, 9) + _validate("POS8", LESSONS_M8, QUESTIONS_M8, 10)
    if problems:
        print("ABORT — not clean:")
        print("\n".join(problems))
        sys.exit(1)

    for name, lessons, questions, key, desc in (
        ("POS 7", LESSONS_M7, QUESTIONS_M7, "voucher_programme",
         "The gift voucher programme end to end: the Voucher Console and its roles, sellable versus complimentary cards with the activation gate and six states, the accounts wired before the first card, design/generate/import, activation with the approver record and the two printing rules, the counter's two selling routes with the daily till-batch check, the register and the permanent void, the four accounting events with breakage as a deliberate finance decision, the monthly check, and the seven watch-points."),
        ("POS 8", LESSONS_M8, QUESTIONS_M8, "honest_counter",
         "Keeping the counter honest: offline's works/waits boundary, the indicators and the queue worked to zero, conflicts re-picked and failed sales never deleted into silence, the fast-checkout decision, End of Day Funds and the five-step daily routine, the nine supervisor watch-patterns with their checks, the routine calendar with the change procedures, the annual handover drill, and the owner's five-number page — closing the ZhiftPOS Professional track."),
    ):
        bank = rebalance(list(questions))
        dist = {c: sum(1 for q in bank if q["ans"] == i) for i, c in enumerate("ABCD")}
        if max(dist.values()) > 10:
            print(f"ABORT — {name} spread failed: {dist}")
            sys.exit(1)
        total = sum(len(l["html"]) for l in lessons)
        print(f"{name} v2: {len(lessons)} chapters ({total:,} chars, min {min(len(l['html']) for l in lessons):,}), bank {len(bank)}, spread {dist}")
        if not CHECK_ONLY:
            data[key]["lessons"] = lessons
            data[key]["questions"] = bank
            data[key]["desc"] = desc

    if CHECK_ONLY:
        print("--check given; no files written.")
        return

    with io.open(os.path.join(root, DATA_PATH), "w", encoding="utf-8") as f:
        json.dump(data, f, indent=1, ensure_ascii=False)
        f.write("\n")
    with io.open(os.path.join(root, INIT), "w", encoding="utf-8") as f:
        f.write(init.replace('"3.156.0"', '"3.157.0"'))
    print("  data: POS 7 + POS 8 lessons + banks REPLACED (style v2.1) — ZhiftPOS track correction COMPLETE")
    print("wrote __version__ -> 3.157.0")


if __name__ == "__main__":
    main()
